import { useId, useMemo, useState } from 'react'
import { displayActionsForContext, projectContextWithWorktree, type ActionContext } from '../../../../data/action_context'
import { dataService } from '../../../../services/data/data_service'
import { isReleasedCardActionContext, RELEASED_CARD_RUN_MESSAGE } from '../../../../../../shared/released_card_actions.mjs'
import { useActions } from '../../../hooks/use_actions'
import { useProjectState } from '../../../hooks/use_project_state'
import { useProjectActionWorktree } from '../../../hooks/use_worktrees'
import { ActionPopupContent } from './action_popup_content'

export { CARD_RUN_POPUP_SIZE_STORAGE_KEY, PROJECT_AGENT_POPUP_SIZE_STORAGE_KEY } from './action_popup_content'

function resolvePopupTarget(context: ActionContext, snapshot: ReturnType<typeof useProjectState>['snapshot']) {
    if (context.kind === 'project') return 'Project'
    if (context.kind !== 'card') return null

    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]

    return cards.find(({ header }) => header.internalId === context.cardInternalId)?.header.id ?? null
}

interface ActionPopupProps {
    anchorElement: HTMLElement | null
    context: ActionContext
    draggable?: boolean
    initialActionId?: string
    onActivate?: () => void
    onClose: () => void
    open?: boolean
    popupEntryId?: string
    stackPosition?: number
}

/** Universal action selector and run popup for the supplied context. */
export function ActionPopup(props: ActionPopupProps) {
    const { anchorElement, context, initialActionId, open } = props
    const { actions: loadedActions } = useActions()
    const { project, snapshot } = useProjectState()
    const projectActionWorktree = useProjectActionWorktree()
    const effectiveContext = useMemo(
        () => projectContextWithWorktree(context, projectActionWorktree),
        [context, projectActionWorktree],
    )
    const actions = useMemo(() => displayActionsForContext(loadedActions, effectiveContext), [effectiveContext, loadedActions])
    const [selectedActionId, setSelectedActionId] = useState<string | null>(initialActionId ?? actions[0]?.id ?? null)
    const [fullHeight, setFullHeight] = useState(false)
    const titleId = useId()
    // A run that edits its own card changes the context (state, title, worktree), so the
    // selected action can drop out of the filtered list mid-run. Keep it selectable instead
    // of closing the popup or silently switching to another action.
    const retainedAction = selectedActionId ? loadedActions.find(({ id }) => id === selectedActionId) ?? null : null
    const selectedAction = actions.find(({ id }) => id === selectedActionId) ?? retainedAction ?? actions[0] ?? null
    const selectableActions = selectedAction && !actions.some(({ id }) => id === selectedAction.id)
        ? [...actions, selectedAction]
        : actions
    const target = resolvePopupTarget(context, snapshot)
    const releasesFolder = dataService.getConfig()?.releasesFolder
    const readOnlyMessage = releasesFolder && isReleasedCardActionContext(effectiveContext, releasesFolder)
        ? RELEASED_CARD_RUN_MESSAGE
        : null

    const handleSelectAction = (actionId: string) => {
        setSelectedActionId(actionId)
    }

    const handleToggleFullHeight = () => setFullHeight((current) => !current)

    if (!selectedAction) return null

    return (
        <ActionPopupContent
            {...props}
            action={selectedAction}
            actions={selectableActions}
            assignmentContext={effectiveContext}
            baseContext={context}
            fullHeight={fullHeight}
            onSelectAction={handleSelectAction}
            onToggleFullHeight={handleToggleFullHeight}
            open={open ?? !!anchorElement}
            primaryPath={project?.rootPath ?? project?.id ?? null}
            readOnlyMessage={readOnlyMessage}
            target={target}
            titleId={titleId}
        />
    )
}

import { Box, ToggleButtonGroup } from '@mui/material'
import type { MouseEvent } from 'react'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionRunStatus } from '../../../../data/action_run_types'
import type { ActionDefinition } from '../../../../data/action_types'
import { useActiveActionRunsForContext } from '../../../hooks/use_action_runs'
import { ActionSelectorButton } from './action_selector_button'

interface ActionSelectorProps {
    actions: ActionDefinition[]
    context: ActionContext
    onSelect: (actionId: string) => void
    selectedAction: ActionDefinition
}

/** Horizontally scrollable, mutually exclusive action selector used by the card Run popup. */
export function ActionSelector(props: ActionSelectorProps) {
    const { actions, context, onSelect, selectedAction } = props
    const activeRuns = useActiveActionRunsForContext(context)
    const activeActionStatuses: Record<string, ActionRunStatus> = {}
    for (const { rootActionId, status } of activeRuns) {
        if (status === 'waitingForInput' || !activeActionStatuses[rootActionId]) activeActionStatuses[rootActionId] = status
    }
    const handleChange = (_event: MouseEvent<HTMLElement>, actionId: string | null) => {
        if (actionId) onSelect(actionId)
    }

    return (
        <Box sx={{ alignItems: 'center', display: 'flex', flex: 1, flexWrap: 'wrap', gap: 1, minWidth: 0 }}>
            <Box sx={{ minWidth: 0 }}>
                <ToggleButtonGroup
                    aria-label="Actions"
                    exclusive
                    onChange={handleChange}
                    size="small"
                    sx={{
                        display: 'flex',
                        flexWrap: 'wrap',
                        gap: 1,
                        '& .MuiToggleButtonGroup-grouped': {
                            bgcolor: 'action.selected',
                            border: '1px solid transparent',
                            borderRadius: '7px !important',
                            color: 'text.secondary',
                            fontSize: 12,
                            fontWeight: 600,
                            height: 26,
                            m: '0 !important',
                            px: 1.5,
                            textTransform: 'none',
                            '&:hover': { bgcolor: 'action.hover', borderColor: 'text.disabled', color: 'text.primary' },
                            '&.Mui-selected': {
                                bgcolor: 'action.selected',
                                borderColor: 'primary.main',
                                color: 'primary.main',
                                '&:hover': { bgcolor: 'action.selected' },
                            },
                        },
                    }}
                    value={selectedAction.id}
                >
                    {actions.map((action) => (
                        <ActionSelectorButton
                            action={action}
                            context={context}
                            key={action.id}
                            liveStatus={activeActionStatuses[action.id]}
                        />
                    ))}
                </ToggleButtonGroup>
            </Box>
        </Box>
    )
}

import { Box, ToggleButton, Tooltip } from '@mui/material'
import Circle from 'mdi-material-ui/Circle'
import HelpCircleOutline from 'mdi-material-ui/HelpCircleOutline'
import Play from 'mdi-material-ui/Play'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionRunStatus } from '../../../../data/action_run_types'
import { CUSTOM_PROMPT_ACTION_ID, type ActionDefinition } from '../../../../data/action_types'
import { useCardActionAgentState } from '../../../hooks/use_card_action_agent_state'

interface ActionSelectorButtonProps {
    action: ActionDefinition
    context: ActionContext
    liveStatus?: ActionRunStatus
}

/** One action selector leaf, including scoped live and persisted agent state. */
export function ActionSelectorButton({ action, context, liveStatus }: ActionSelectorButtonProps) {
    const persistedState = useCardActionAgentState(action.id, context)
    const hasLiveState = liveStatus === 'queued' || liveStatus === 'running' || liveStatus === 'waitingForInput'
    const isQueued = liveStatus === 'queued'
    const isWaiting = liveStatus === 'waitingForInput' || (!hasLiveState && persistedState === 'waiting for input')
    const isRunning = liveStatus === 'running' || (!hasLiveState && persistedState === 'running')
    const hasUnseenResult = !hasLiveState && persistedState === 'unseen result'
    const accessibleLabel = action.id === CUSTOM_PROMPT_ACTION_ID ? 'Custom prompt' : action.label
    const stateDescription = isQueued
        ? 'Action is queued'
        : isWaiting
            ? 'Agent is waiting for input'
            : isRunning
                ? 'Agent is running'
                : hasUnseenResult
                    ? 'New agent result available'
                    : null

    return (
        <Tooltip
            describeChild
            title={isQueued ? stateDescription : isWaiting ? stateDescription : action.description}
        >
            <ToggleButton
                aria-label={stateDescription ? `${accessibleLabel} â€” ${stateDescription}` : accessibleLabel}
                sx={(theme) => ({
                    overflow: 'hidden',
                    position: 'relative',
                    ...(isWaiting && {
                        '&.MuiToggleButton-root.MuiToggleButtonGroup-grouped': {
                            borderColor: 'warning.main',
                            color: 'warning.main',
                            '&:hover': { borderColor: 'warning.main', color: 'warning.main' },
                            '&.Mui-selected': {
                                borderColor: 'warning.main',
                                color: 'warning.main',
                            },
                        },
                    }),
                    ...(isRunning && {
                        '@keyframes md2-action-run-spin': { to: { transform: 'rotate(1turn)' } },
                        '&::after': {
                            backgroundColor: theme.palette.action.selected,
                            borderRadius: '5.5px',
                            content: '""',
                            inset: '1.5px',
                            pointerEvents: 'none',
                            position: 'absolute',
                        },
                        '&::before': {
                            animation: 'md2-action-run-spin 1s linear infinite',
                            background: `conic-gradient(from 0deg, ${theme.palette.primary.main}, transparent 55%)`,
                            content: '""',
                            inset: '-100%',
                            pointerEvents: 'none',
                            position: 'absolute',
                        },
                    }),
                })}
                value={action.id}
            >
                <Box component="span" sx={{ alignItems: 'center', display: 'inline-flex', gap: 0.5, position: 'relative', zIndex: 1 }}>
                    {isWaiting ? <HelpCircleOutline aria-hidden sx={{ fontSize: 13 }} /> : null}
                    {isRunning ? <Play aria-hidden sx={{ fontSize: 13 }} /> : null}
                    {action.label}
                </Box>
                {hasUnseenResult ? (
                    <Circle
                        aria-hidden
                        sx={{ color: 'info.main', fontSize: 8, position: 'absolute', right: 2, top: 2, zIndex: 1 }}
                    />
                ) : null}
            </ToggleButton>
        </Tooltip>
    )
}

import { IconButton, ListItemIcon, MenuItem, Stack, Tooltip } from '@mui/material'
import { useEffect, useMemo, useState } from 'react'
import type { MouseEvent } from 'react'
import { displayActionsForContext, type ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { dialogService } from '../../../../services/dialog_service'
import { useActions } from '../../../hooks/use_actions'
import { useRunningActionForContext } from '../../../hooks/use_action_runs'
import { ActionIcon } from './action_icon'
import { resolveActionIcon, type ActionIconSource } from './action_icon_resolver'
import { ActionPopup } from '../popup/action_popup'
import { useProjectReadOnly } from '../../../hooks/use_project_read_only'

/** How action entry points are rendered in an existing toolbar or menu. */
export type ActionEntryVariant = 'icons' | 'menuItems'
export type ActionEntryVisibility = 'all-matching' | 'explicit-context'

interface ActionEntryPointsProps {
    context: ActionContext
    onMenuItemSelected?: () => void
    popupAnchorElement?: HTMLElement | null
    variant: ActionEntryVariant
    visibility?: ActionEntryVisibility
}

const DEFAULT_ICON_SOURCE: ActionIconSource = { dataUri: null }

interface ActionPopupState {
    actionId: string
    anchorElement: HTMLElement
}

/**
 * Context-sensitive action entry points shown close to a card/file/folder. Filters
 * the loaded actions by `appliesTo`, and on activation opens a resizable popup bound
 * to the action and context. `before`/`after` shortcuts push a new popup for the
 * related action with the same context.
 */
export function ActionEntryPoints(props: ActionEntryPointsProps) {
    const { context, onMenuItemSelected, popupAnchorElement, variant, visibility = 'all-matching' } = props
    const { actions: loadedActions } = useActions()
    const runningRun = useRunningActionForContext(context)
    const readOnly = useProjectReadOnly()
    const runDisabled = readOnly || !!runningRun
    const [iconSources, setIconSources] = useState<Record<string, ActionIconSource>>({})
    const [popupState, setPopupState] = useState<ActionPopupState | null>(null)

    const matching = useMemo(() => {
        const contextActions = displayActionsForContext(loadedActions, context)
        if (visibility === 'explicit-context') {
            return contextActions.filter((action) => action.appliesTo?.kind === context.kind)
        }

        return contextActions
    }, [context, loadedActions, visibility])

    useEffect(() => {
        let isActive = true

        const loadIcons = async () => {
            const entries = await Promise.all(matching.map(async (action) => [action.id, await resolveActionIcon(action.icon)] as const))
            if (!isActive) return

            setIconSources(Object.fromEntries(entries))
        }

        void loadIcons()

        return () => {
            isActive = false
        }
    }, [matching])

    if (matching.length === 0) return null

    const open = (actionId: string, anchorElement: HTMLElement) => {
        onMenuItemSelected?.()
        setPopupState({ actionId, anchorElement })
    }

    const handleOpen = (event: MouseEvent<HTMLElement>) => {
        try {
            const { actionId } = event.currentTarget.dataset
            if (!actionId) throw new Error('Missing action id on action entry point')

            open(actionId, popupAnchorElement ?? event.currentTarget)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Action popup could not be opened' })
        }
    }

    const iconSourceFor = (action: ActionDefinition) => iconSources[action.id] ?? DEFAULT_ICON_SOURCE

    const closePopup = () => {
        setPopupState(null)
    }

    const popup = popupState ? (
        <ActionPopup
            anchorElement={popupState.anchorElement}
            context={context}
            draggable
            initialActionId={popupState.actionId}
            key={popupState.actionId}
            onClose={closePopup}
        />
    ) : null

    const menuItems = (
        <>
            {matching.map((action) => (
                <MenuItem
                    data-action-id={action.id}
                    disabled={runDisabled}
                    key={action.id}
                    onClick={handleOpen}
                >
                    <ListItemIcon>
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </ListItemIcon>
                    {action.label}
                </MenuItem>
            ))}
            {popup}
        </>
    )

    if (variant === 'menuItems') return menuItems

    return (
        <Stack direction="row" spacing={0.25} sx={{ flexShrink: 0 }}>
            {matching.map((action) => (
                <Tooltip key={action.id} title={action.label}>
                    <IconButton
                        aria-label={action.label}
                        data-action-id={action.id}
                        disabled={runDisabled}
                        onClick={handleOpen}
                        size="small"
                    >
                        <ActionIcon fontSize="small" source={iconSourceFor(action)} />
                    </IconButton>
                </Tooltip>
            ))}
            {popup}
        </Stack>
    )
}

import type { AgentConversation } from '../../data/data_types'

export type CardAgentState = 'idle' | 'running' | 'unseen result' | 'waiting for input'

/** Newest not-yet-viewed conversation for one action, or null when all are viewed. */
export function latestUnseenConversation(conversations: AgentConversation[], actionId: string) {
    return [...conversations]
        .filter((conversation) => conversation.actionId === actionId && !conversation.viewed)
        .sort((left, right) => right.startedAt.localeCompare(left.startedAt))[0] ?? null
}

/** True when any conversation has not been viewed yet. */
export function hasUnseenConversation(conversations: AgentConversation[]) {
    return conversations.some(({ viewed }) => !viewed)
}

function isConversationWaiting(conversations: AgentConversation[]) {
    return conversations.some((conversation) => {
        if (conversation.status === 'waitingForInput') return true
        if (conversation.status !== 'running') return false

        const stateEvent = conversation.entries.findLast((entry) => (
            entry.kind === 'event' && (entry.type === 'waiting' || entry.type === 'resumed')
        ))

        return stateEvent?.kind === 'event' && stateEvent.type === 'waiting'
    })
}

/** True when the card has at least one agent conversation still running. */
export function hasRunningConversation(conversations: AgentConversation[]) {
    return conversations.some((conversation) => (
        conversation.status === 'running' || conversation.status === 'waitingForInput'
    ))
}

/** Resolve the single agent state shown for a card, mirroring the priority waiting > running > unseen > idle. */
export function cardAgentState(conversations: AgentConversation[]): CardAgentState {
    if (isConversationWaiting(conversations)) return 'waiting for input'
    if (hasRunningConversation(conversations)) return 'running'
    if (hasUnseenConversation(conversations)) return 'unseen result'

    return 'idle'
}

/** Human-readable description of an agent state, or null when idle. */
export function agentStateDescription(agentState: CardAgentState): string | null {
    if (agentState === 'waiting for input') return 'Agent is waiting for input'
    if (agentState === 'running') return 'Agent is running'
    if (agentState === 'unseen result') return 'New agent result available'

    return null
}

import type { ActionRunEvent, ActionRunStatus } from '../../data/action_run_types'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import type { AgentConversation } from '../../data/data_types'
import { actionRunRegistry } from '../actions/action_run_registry'
import { dialogService } from '../dialog_service'
import { register } from '../service_injector'

const UNSEEN_STATUSES = new Set<ActionRunStatus>(['completed', 'failed', 'waitingForInput'])

type ResolveStoredConversation = (conversation: AgentConversation) => AgentConversation | null

/** Event type dispatched for aggregate acknowledgement changes on one card. */
export function cardAcknowledgementEvent(cardInternalId: string) {
    return `card-${cardInternalId}`
}

/** Event type dispatched for acknowledgement changes on one card action. */
export function actionAcknowledgementEvent(cardInternalId: string, actionId: string) {
    return `action-${cardInternalId}-${actionId}`
}

function conversationKey(cardInternalId: string, actionId: string, conversationId: string) {
    return `${cardInternalId}-${actionId}-${conversationId}`
}

async function persistConversationViewed(reference: string, viewed: boolean) {
    const bridge = getElectronActionBridge()
    if (!bridge?.updateActionConversationViewed) throw new Error('Updating conversation view state requires Electron')

    return bridge.updateActionConversationViewed(reference, viewed)
}

/**
 * Tracks chat visibility and persists conversation view state.
 * Changes are announced through scoped card and card-action events so only affected leaves update;
 * the conversation data itself lives in the agent integration store and the activity files.
 * Scoping uses the stable card internal ID so card renames cannot break acknowledgement state.
 */
export class AgentAcknowledgementService extends EventTarget {
    private readonly lastRunStatuses = new Map<string, ActionRunStatus>()
    private resolveStoredConversation: ResolveStoredConversation | null = null
    private readonly visibleEntries = new Map<string, Set<string>>()

    constructor() {
        super()
        actionRunRegistry.subscribeActiveRunEvents(this.handleActionRunEvent)
    }

    /** Connects the loaded-conversation store so view changes land on the canonical conversation records. */
    connectConversationStore(resolveStoredConversation: ResolveStoredConversation) {
        this.resolveStoredConversation = resolveStoredConversation
    }

    /** Announce acknowledgement-relevant conversation changes to the scoped card and card-action subscribers. */
    announceConversationsChanged(cardInternalId: string, actionIds: string[]) {
        for (const actionId of new Set(actionIds)) {
            this.dispatchEvent(new Event(actionAcknowledgementEvent(cardInternalId, actionId)))
        }
        this.dispatchEvent(new Event(cardAcknowledgementEvent(cardInternalId)))
    }

    setConversationVisible(
        entryId: string,
        cardInternalId: string,
        actionId: string,
        conversation: AgentConversation,
        visible: boolean,
    ) {
        const key = conversationKey(cardInternalId, actionId, conversation.id)
        const entries = this.visibleEntries.get(key) ?? new Set<string>()
        if (visible) entries.add(entryId)
        else entries.delete(entryId)
        if (entries.size > 0) this.visibleEntries.set(key, entries)
        else this.visibleEntries.delete(key)
        const current = this.resolveStoredConversation?.(conversation) ?? conversation
        if (visible && !current.viewed) {
            void this.setViewed(cardInternalId, actionId, conversation, true).catch(() => undefined)
        }
    }

    async setViewed(cardInternalId: string, actionId: string, conversation: AgentConversation, viewed: boolean) {
        const current = this.resolveStoredConversation?.(conversation) ?? conversation
        if (current.viewed === viewed) return current

        try {
            await persistConversationViewed(conversation.path, viewed)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card conversation view state could not be saved' })
            throw error
        }
        current.viewed = viewed
        conversation.viewed = viewed
        this.announceConversationsChanged(cardInternalId, [actionId])

        return current
    }

    /** Clears transient state at a project boundary. */
    reset() {
        this.lastRunStatuses.clear()
        this.visibleEntries.clear()
    }

    private readonly handleActionRunEvent = (event: ActionRunEvent) => {
        const previousStatus = this.lastRunStatuses.get(event.runId)
        this.lastRunStatuses.set(event.runId, event.status)
        if (previousStatus === event.status || !UNSEEN_STATUSES.has(event.status)) return

        const conversation = actionRunRegistry.getRunStore(event.runId)?.getSnapshot().conversation ?? null
        const cardInternalId = event.context.cardInternalId
        const actionId = conversation?.actionId
        if (!cardInternalId || !conversation || !actionId) return
        if ((this.visibleEntries.get(conversationKey(cardInternalId, actionId, conversation.id))?.size ?? 0) > 0) return

        void this.setViewed(cardInternalId, actionId, conversation, false).catch(() => undefined)
    }

}

export const agentAcknowledgementService = register('agentAcknowledgementService', new AgentAcknowledgementService())

import type { ActionContext } from '../../data/action_context'
import { useActionAgentState } from './use_agent_acknowledgements'
import { useActionContextCard } from './use_action_context_card'

/** Persisted agent state for one action in a card context. */
export function useCardActionAgentState(actionId: string, context: ActionContext) {
    const { card } = useActionContextCard(context)
    const cardInternalId = card?.header.internalId ?? context.cardInternalId

    return useActionAgentState(cardInternalId, actionId)
