import { useCallback, useSyncExternalStore } from 'react'
import {
    actionAcknowledgementEvent,
    agentAcknowledgementService,
    cardAcknowledgementEvent,
} from '../../services/agents/agent_acknowledgement_service'
import { cardAgentState, latestUnseenConversation } from '../../services/agents/card_agent_state'
import { dataService } from '../../services/data/data_service'

function subscribeToAcknowledgements(eventTypes: string[], onStoreChange: () => void) {
    for (const eventType of eventTypes) agentAcknowledgementService.addEventListener(eventType, onStoreChange)

    return () => {
        for (const eventType of eventTypes) agentAcknowledgementService.removeEventListener(eventType, onStoreChange)
    }
}

/** Reads the live conversations of a card, which a rendered card copy cannot provide. */
export function cardConversations(cardInternalId: string | null | undefined) {
    return cardInternalId ? dataService.agents.getAgentConversations(cardInternalId) : []
}

/**
 * Agent state of one card, refreshed on that card's scoped conversation events.
 * Conversations are read from the agent store on every snapshot, so newly attached or
 * acknowledged conversations are picked up without republishing the card.
 */
export function useCardAgentState(cardInternalId: string | null | undefined) {
    const subscribe = useCallback((onStoreChange: () => void) => (
        cardInternalId
            ? subscribeToAcknowledgements([cardAcknowledgementEvent(cardInternalId)], onStoreChange)
            : () => undefined
    ), [cardInternalId])
    const getSnapshot = useCallback(() => cardAgentState(cardConversations(cardInternalId)), [cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Agent state of one card action, refreshed only by that action's scoped conversation event. */
export function useActionAgentState(cardInternalId: string | null | undefined, actionId: string) {
    const subscribe = useCallback((onStoreChange: () => void) => (
        cardInternalId
            ? subscribeToAcknowledgements([actionAcknowledgementEvent(cardInternalId, actionId)], onStoreChange)
            : () => undefined
    ), [actionId, cardInternalId])
    const getSnapshot = useCallback(() => cardAgentState(
        cardConversations(cardInternalId).filter((conversation) => conversation.actionId === actionId),
    ), [actionId, cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

/** Identifies the unseen conversations of the given card actions, refreshed on their scoped events. */
export function useActionsUnseenKey(cardInternalId: string | null | undefined, actionIds: string[]) {
    const actionIdsKey = [...new Set(actionIds)].sort().join(',')
    const subscribe = useCallback((onStoreChange: () => void) => {
        if (!cardInternalId) return () => undefined
        const eventTypes = actionIdsKey.split(',')
            .filter((actionId) => actionId.length > 0)
            .map((actionId) => actionAcknowledgementEvent(cardInternalId, actionId))

        return subscribeToAcknowledgements(eventTypes, onStoreChange)
    }, [actionIdsKey, cardInternalId])
    const getSnapshot = useCallback(() => {
        const conversations = cardConversations(cardInternalId)

        return actionIdsKey.split(',')
            .map((actionId) => latestUnseenConversation(conversations, actionId)?.id ?? '')
            .join(',')
    }, [actionIdsKey, cardInternalId])

    return useSyncExternalStore(subscribe, getSnapshot, getSnapshot)
}

import type { ActionContext } from '../../data/action_context'
import { useProjectState } from './use_project_state'

/** Resolves current card data for a leaf bound to a stable action context. */
export function useActionContextCard(context: ActionContext) {
    const { snapshot } = useProjectState()
    const cards = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
    const card = context.cardInternalId
        ? cards.find(({ header }) => header.internalId === context.cardInternalId) ?? null
        : cards.find(({ path }) => path === context.file) ?? null

    return { card, cardPath: card?.path ?? context.file ?? null }
}

import type { ActionRunEvent, ActionRunStatus } from '../../data/action_run_types'
import { getElectronActionBridge } from '../../data/electron_action_bridge'
import type { AgentConversation } from '../../data/data_types'
import { actionRunRegistry } from '../actions/action_run_registry'
import { dialogService } from '../dialog_service'
import { register } from '../service_injector'

const UNSEEN_STATUSES = new Set<ActionRunStatus>(['completed', 'failed', 'waitingForInput'])

type ResolveStoredConversation = (conversation: AgentConversation) => AgentConversation | null

/** Event type dispatched for aggregate acknowledgement changes on one card. */
export function cardAcknowledgementEvent(cardInternalId: string) {
    return `card-${cardInternalId}`
}

/** Event type dispatched for acknowledgement changes on one card action. */
export function actionAcknowledgementEvent(cardInternalId: string, actionId: string) {
    return `action-${cardInternalId}-${actionId}`
}

function conversationKey(cardInternalId: string, actionId: string, conversationId: string) {
    return `${cardInternalId}-${actionId}-${conversationId}`
}

async function persistConversationViewed(reference: string, viewed: boolean) {
    const bridge = getElectronActionBridge()
    if (!bridge?.updateActionConversationViewed) throw new Error('Updating conversation view state requires Electron')

    return bridge.updateActionConversationViewed(reference, viewed)
}

/**
 * Tracks chat visibility and persists conversation view state.
 * Changes are announced through scoped card and card-action events so only affected leaves update;
 * the conversation data itself lives in the agent integration store and the activity files.
 * Scoping uses the stable card internal ID so card renames cannot break acknowledgement state.
 */
export class AgentAcknowledgementService extends EventTarget {
    private readonly lastRunStatuses = new Map<string, ActionRunStatus>()
    private resolveStoredConversation: ResolveStoredConversation | null = null
    private readonly visibleEntries = new Map<string, Set<string>>()

    constructor() {
        super()
        actionRunRegistry.subscribeActiveRunEvents(this.handleActionRunEvent)
    }

    /** Connects the loaded-conversation store so view changes land on the canonical conversation records. */
    connectConversationStore(resolveStoredConversation: ResolveStoredConversation) {
        this.resolveStoredConversation = resolveStoredConversation
    }

    /** Announce acknowledgement-relevant conversation changes to the scoped card and card-action subscribers. */
    announceConversationsChanged(cardInternalId: string, actionIds: string[]) {
        for (const actionId of new Set(actionIds)) {
            this.dispatchEvent(new Event(actionAcknowledgementEvent(cardInternalId, actionId)))
        }
        this.dispatchEvent(new Event(cardAcknowledgementEvent(cardInternalId)))
    }

    setConversationVisible(
        entryId: string,
        cardInternalId: string,
        actionId: string,
        conversation: AgentConversation,
        visible: boolean,
    ) {
        const key = conversationKey(cardInternalId, actionId, conversation.id)
        const entries = this.visibleEntries.get(key) ?? new Set<string>()
        if (visible) entries.add(entryId)
        else entries.delete(entryId)
        if (entries.size > 0) this.visibleEntries.set(key, entries)
        else this.visibleEntries.delete(key)
        const current = this.resolveStoredConversation?.(conversation) ?? conversation
        if (visible && !current.viewed) {
            void this.setViewed(cardInternalId, actionId, conversation, true).catch(() => undefined)
        }
    }

    async setViewed(cardInternalId: string, actionId: string, conversation: AgentConversation, viewed: boolean) {
        const current = this.resolveStoredConversation?.(conversation) ?? conversation
        if (current.viewed === viewed) return current

        try {
            await persistConversationViewed(conversation.path, viewed)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Card conversation view state could not be saved' })
            throw error
        }
        current.viewed = viewed
        conversation.viewed = viewed
        this.announceConversationsChanged(cardInternalId, [actionId])

        return current
    }

    /** Clears transient state at a project boundary. */
    reset() {
        this.lastRunStatuses.clear()
        this.visibleEntries.clear()
    }

    private readonly handleActionRunEvent = (event: ActionRunEvent) => {
        const previousStatus = this.lastRunStatuses.get(event.runId)
        this.lastRunStatuses.set(event.runId, event.status)
        if (previousStatus === event.status || !UNSEEN_STATUSES.has(event.status)) return

        const conversation = actionRunRegistry.getRunStore(event.runId)?.getSnapshot().conversation ?? null
        const cardInternalId = event.context.cardInternalId
        const actionId = conversation?.actionId
        if (!cardInternalId || !conversation || !actionId) return
        if ((this.visibleEntries.get(conversationKey(cardInternalId, actionId, conversation.id))?.size ?? 0) > 0) return

        void this.setViewed(cardInternalId, actionId, conversation, false).catch(() => undefined)
    }

}

export const agentAcknowledgementService = register('agentAcknowledgementService', new AgentAcknowledgementService())

import type { AgentConversation } from '../../data/data_types'

export type CardAgentState = 'idle' | 'running' | 'unseen result' | 'waiting for input'

/** Newest not-yet-viewed conversation for one action, or null when all are viewed. */
export function latestUnseenConversation(conversations: AgentConversation[], actionId: string) {
    return [...conversations]
        .filter((conversation) => conversation.actionId === actionId && !conversation.viewed)
        .sort((left, right) => right.startedAt.localeCompare(left.startedAt))[0] ?? null
}

/** True when any conversation has not been viewed yet. */
export function hasUnseenConversation(conversations: AgentConversation[]) {
    return conversations.some(({ viewed }) => !viewed)
}

function isConversationWaiting(conversations: AgentConversation[]) {
    return conversations.some((conversation) => {
        if (conversation.status === 'waitingForInput') return true
        if (conversation.status !== 'running') return false

        const stateEvent = conversation.entries.findLast((entry) => (
            entry.kind === 'event' && (entry.type === 'waiting' || entry.type === 'resumed')
        ))

        return stateEvent?.kind === 'event' && stateEvent.type === 'waiting'
    })
}

/** True when the card has at least one agent conversation still running. */
export function hasRunningConversation(conversations: AgentConversation[]) {
    return conversations.some((conversation) => (
        conversation.status === 'running' || conversation.status === 'waitingForInput'
    ))
}

/** Resolve the single agent state shown for a card, mirroring the priority waiting > running > unseen > idle. */
export function cardAgentState(conversations: AgentConversation[]): CardAgentState {
    if (isConversationWaiting(conversations)) return 'waiting for input'
    if (hasRunningConversation(conversations)) return 'running'
    if (hasUnseenConversation(conversations)) return 'unseen result'

    return 'idle'
}

/** Human-readable description of an agent state, or null when idle. */
export function agentStateDescription(agentState: CardAgentState): string | null {
    if (agentState === 'waiting for input') return 'Agent is waiting for input'
    if (agentState === 'running') return 'Agent is running'
    if (agentState === 'unseen result') return 'New agent result available'

    return null
}

import { Fab, Tooltip } from '@mui/material'
import RobotOutline from 'mdi-material-ui/RobotOutline'
import { useRef, useState } from 'react'
import type { MouseEvent, PointerEvent as ReactPointerEvent } from 'react'
import { projectContext } from '../../data/action_context'
